CustomField.formula:
OR(

/* Working → less than 8 hours */
AND(
    ISPICKVAL(Status__c, 'Working'),
    NOT(ISBLANK(Login_Time__c)),
    NOT(ISBLANK(Logout_Time__c)),
    (Logout_Time__c - Login_Time__c) < (8 * 3600000)
),

/* Half Day → less than 4 hours */
AND(
    OR(
        ISPICKVAL(Status__c, 'Half Day - FH'),
        ISPICKVAL(Status__c, 'Half Day - SH')
    ),
    NOT(ISBLANK(Login_Time__c)),
    NOT(ISBLANK(Logout_Time__c)),
    (Logout_Time__c - Login_Time__c) < (4 * 3600000)
)

)
